#include "PlantDefinition.h"
bool UPlantDefinition::ValidateDefinition(FString& OutError) const { if(PlantID.IsNone()){OutError=TEXT("PlantID boş");return false;} if(StageThresholds.IsEmpty()){OutError=TEXT("StageThresholds boş");return false;} if(BaseTemperature>=MaxTemperature){OutError=TEXT("BaseTemperature >= MaxTemperature");return false;} float Prev=-1.f; for(const auto& S:StageThresholds){if(S.GDDRequired<0.f||S.GDDRequired<=Prev){OutError=TEXT("GDD eşikleri negatif veya artan değil");return false;} Prev=S.GDDRequired;} OutError.Reset();return true; }
EGrowthStage UPlantDefinition::GetStageForGDD(float GDD) const { EGrowthStage Result=EGrowthStage::Seed; for(const auto& S:StageThresholds){if(GDD>=S.GDDRequired)Result=S.Stage;else break;} return Result; }
float UPlantDefinition::GetStageProgress(float GDD) const {if(StageThresholds.IsEmpty())return 0.f; for(int32 I=0;I<StageThresholds.Num();++I){if(GDD<StageThresholds[I].GDDRequired){const float Prev=I?StageThresholds[I-1].GDDRequired:0.f;const float Range=StageThresholds[I].GDDRequired-Prev;return Range>SMALL_NUMBER?FMath::Clamp((GDD-Prev)/Range,0.f,1.f):1.f;}}return 1.f;}
float UPlantDefinition::GetTotalGDDToMaturity() const {for(int32 I=StageThresholds.Num()-1;I>=0;--I)if(StageThresholds[I].Stage==EGrowthStage::Maturity)return StageThresholds[I].GDDRequired; return StageThresholds.IsEmpty()?0.f:StageThresholds.Last().GDDRequired;}
